75	/// Export a frame into an SVG suitable for embedding into HTML.
76	///
77	/// Takes additional `anchor` locations that will be serialized as linkable
78	/// points. This enables other documents in the bundle to link into the
79	/// resulting SVG. Also takes a `link_resolver` for resolving links between the
80	/// frame and remaining document.
81	#[typst_macros::time(name = "svg in html")]
82	pub fn svg_in_html(
83	    frame: &Frame,
84	    text_size: Abs,
85	    pretty: bool,
86	    id: Option<&str>,
87	    styles: &str,
88	    anchors: &[(Point, EcoString)],
89	    link_resolver: Tracked<LateLinkResolver>,
90	) -> String {
91	    let mut renderer = SVGRenderer::with_options(Some(link_resolver));
92	    let mut xml = XmlWriter::new(xml_options(pretty));
93	    let mut svg = svg_header_with_custom_attrs(&mut xml, frame.size(), |svg| {
94	        if let Some(id) = id {
95	            svg.attr("id", id);
96	        }
97	        svg.attr_with("style", |attr| {
98	            // TODO: Maybe make this a little more elegant?
99	            attr.push_str("overflow: visible; width: ");
100	            attr.push_num(frame.width() / text_size);
101	            attr.push_str("em; height: ");
102	            attr.push_num(frame.height() / text_size);
103	            attr.push_str("em;");
104	            if !styles.is_empty() {
105	                attr.push_str(" ");
106	                attr.push_str(styles);
107	            }
108	        });
109	    });
110	
111	    let state = State::new(frame.size());
112	    renderer.render_frame(&mut svg, &state, frame);
113	
114	    for (pos, id) in anchors {
115	        renderer.render_anchor(&mut svg, *pos, id);
116	    }
117	
118	    renderer.finalize(svg);
119	    xml.end_document()
120	}
