474	/// Deduplicates its elements. It is used to deduplicate glyphs and clip paths.
475	/// The `H` is the hash type, and `T` is the value type. The `PREFIX` is the
476	/// prefix of the index. This is used to distinguish between glyphs and clip
477	/// paths.
478	#[derive(Debug, Default, Clone)]
479	struct Deduplicator<T> {
480	    kind: char,
481	    map: IndexMap<u128, T, FxBuildHasher>,
482	}
483	
484	impl<T> Deduplicator<T> {
485	    fn new(kind: char) -> Self {
486	        Self { kind, map: IndexMap::default() }
487	    }
488	
489	    /// Inserts a value into the vector. If the hash is already present, returns
490	    /// the index of the existing value and `f` will not be called. Otherwise,
491	    /// inserts the value and returns the id of the inserted value.
492	    #[must_use = "returns the id of the inserted value"]
493	    fn insert_with<K, F>(&mut self, key: K, f: F) -> DedupId
494	    where
495	        K: Hash,
496	        F: FnOnce() -> T,
497	    {
498	        self.insert_with_val(key, f).0
499	    }
500	
501	    /// Same as [`Self::insert_with`], but it also returns a reference to the
502	    /// cached or inserted value.
503	    #[must_use]
504	    fn insert_with_val<K, F>(&mut self, key: K, f: F) -> (DedupId, &mut T)
505	    where
506	        K: Hash,
507	        F: FnOnce() -> T,
508	    {
509	        let hash = typst_utils::hash128(&key);
510	        let val = self.map.entry(hash).or_insert_with(f);
511	        (DedupId(self.kind, hash), val)
512	    }
513	
514	    /// Iterate over the elements alongside their ids.
515	    fn iter(&self) -> impl Iterator<Item = (DedupId, &T)> {
516	        self.map.iter().map(|(hash, v)| (DedupId(self.kind, *hash), v))
517	    }
518	
519	    /// Returns true if the deduplicator is empty.
520	    fn is_empty(&self) -> bool {
521	        self.map.is_empty()
522	    }
523	}
524	
525	/// Identifies a `<def>`.
526	#[derive(Debug, Copy, Clone, Eq, PartialEq, Ord, PartialOrd, Hash)]
527	struct DedupId(char, u128);
528	
529	impl SvgDisplay for DedupId {
530	    fn fmt(&self, f: &mut impl SvgWrite) {
531	        let Self(kind, hash) = *self;
532	        f.push_char(kind);
533	
534	        let mut digits = [0; 32];
535	        for (i, byte) in hash.to_be_bytes().into_iter().enumerate() {
536	            digits[2 * i] = to_hex_digit((byte >> 4) & 0x0F);
