8	pub struct SvgElem<'a> {
9	    xml: &'a mut XmlWriter,
10	}
11	
12	impl<'a> SvgElem<'a> {
13	    pub fn new(xml: &'a mut XmlWriter, name: &str) -> Self {
14	        xml.start_element(name);
15	        Self { xml }
16	    }
17	
18	    pub fn elem(&mut self, name: &str) -> SvgElem<'_> {
19	        SvgElem::new(self.xml, name)
20	    }
21	
22	    /// Creates a [`LazySvgElem`].
23	    pub fn lazy_elem<'b>(&'b mut self, name: &'static str) -> LazySvgElem<'a, 'b> {
24	        LazySvgElem::new(self, name)
25	    }
26	
27	    /// Write an SVG attribute.
28	    pub fn attr(&mut self, name: &str, value: impl SvgDisplay) -> &mut Self {
29	        self.attr_with(name, |attr| value.fmt(attr));
30	        self
31	    }
32	
33	    /// Write an SVG attribute, to an [`SvgFormatter`].
34	    pub fn attr_with(
35	        &mut self,
36	        name: &str,
37	        fmt: impl FnOnce(&mut SvgFormatter),
38	    ) -> &mut Self {
39	        self.xml
40	            .write_attribute_raw(name, |buf| fmt(&mut SvgFormatter::new(buf)));
41	        self
42	    }
43	
44	    pub fn with(&mut self, f: impl FnOnce(&mut Self)) -> &mut Self {
45	        f(self);
46	        self
47	    }
48	}
49	
50	impl Drop for SvgElem<'_> {
51	    fn drop(&mut self) {
52	        self.xml.end_element();
53	    }
54	}
55	
56	/// Allows deferring the creation of a children element.
57	pub struct LazySvgElem<'a, 'b> {
58	    inner: &'b mut SvgElem<'a>,
59	    initialized: bool,
60	    name: &'static str,
61	}
62	
63	impl<'a, 'b> LazySvgElem<'a, 'b> {
64	    pub fn new(parent: &'b mut SvgElem<'a>, name: &'static str) -> Self {
65	        Self { inner: parent, initialized: false, name }
66	    }
67	
68	    /// Initialize the child element, if not already present.
69	    pub fn init<'c>(&'c mut self) -> &'c mut SvgElem<'a> {
70	        if !self.initialized {
71	            self.inner.xml.start_element(self.name);
72	            self.initialized = true;
73	        }
74	        self.inner
75	    }
76	
77	    /// Either get the child element, if it has been initialized, otherwise get
78	    /// the parent.
79	    pub fn lazy<'c>(&'c mut self) -> &'c mut SvgElem<'a> {
80	        self.inner
81	    }
82	}
83	
84	impl Drop for LazySvgElem<'_, '_> {
85	    fn drop(&mut self) {
86	        if self.initialized {
87	            self.inner.xml.end_element();
88	        }
89	    }
90	}
91	
92	pub trait SvgWrite: Sized {
93	    /// Write a string. When writing to an attribute value, XML metacharacters
94	    /// are escaped.
95	    fn push_str(&mut self, value: &str);
96	
97	    /// Write a character. When writing to an attribute value, XML
98	    /// metacharacters are escaped.
99	    fn push_char(&mut self, value: char) {
100	        self.push_str(value.encode_utf8(&mut [0; 4]));
101	    }
102	
103	    /// Write a number.
104	    fn push_num(&mut self, num: f64) {
105	        const ROUNDING_FACTOR: f64 = 10_u32.pow(9) as f64;
106	
107	        // Round numbers to the specified precision to make them more
108	        // deterministic and to reduce the file size.
109	        let num = (ROUNDING_FACTOR * num).round() / ROUNDING_FACTOR;
110	
111	        // If the number is an integer, format it using `itoa`. This should be
112	        // faster and avoids the `.0`.
113	        if num == num as i64 as f64 {
114	            self.push_int(num as i64);
115	            return;
116	        }
117	
118	        let mut buf = ryu::Buffer::new();
119	        self.push_str(buf.format(num));
120	    }
121	
122	    /// Write an integer.
123	    fn push_int(&mut self, num: i64) {
124	        let mut buf = itoa::Buffer::new();
125	        self.push_str(buf.format(num));
126	    }
