1	use ecow::EcoString;
2	use ttf_parser::GlyphId;
3	use typst_library::layout::{Abs, Ratio, Size, Transform};
4	use typst_library::text::TextItem;
5	use typst_library::text::color::{
6	    GlyphFrame, GlyphFrameItem, glyph_frame, should_outline,
7	};
8	use typst_library::visualize::{FillRule, Paint, RelativeTo};
9	
10	use crate::path::SvgPathBuilder;
11	use crate::write::{SvgElem, SvgIdRef, SvgTransform};
12	use crate::{DedupId, SVGRenderer, State};
13	
14	/// Represents a glyph to be rendered.
15	#[derive(Clone)]
16	pub enum RenderedGlyph {
17	    /// A frame that contains an image glpyh.
18	    Frame(GlyphFrame),
19	    /// A path is a sequence of drawing commands.
20	    ///
21	    /// It is in the format of `M x y L x y C x1 y1 x2 y2 x y Z`.
22	    Path(EcoString),
23	}
24	
25	impl SVGRenderer<'_> {
26	    /// Render a text item. The text is rendered as a group of glyphs. We will
27	    /// try to render the text as SVG first, then bitmap, then outline. If none
28	    /// of them works, we will skip the text.
29	    pub(super) fn render_text(
30	        &mut self,
31	        svg: &mut SvgElem,
32	        state: &State,
33	        text: &TextItem,
34	    ) {
35	        let svg = &mut svg.elem("g");
36	
37	        // Flip the transform since fonts use a Y-Up coordinate system.
38	        let state = state.pre_concat(Transform::scale(Ratio::one(), -Ratio::one()));
39	        svg.attr("transform", SvgTransform(state.transform));
40	
41	        let mut x = Abs::pt(0.0);
42	        let mut y = Abs::pt(0.0);
43	        for glyph in &text.glyphs {
44	            let id = GlyphId(glyph.id);
45	            let x_offset = x + glyph.x_offset.at(text.size);
46	            let y_offset = y + glyph.y_offset.at(text.size);
47	
48	            self.render_glyph(svg, &state, text, id, x_offset, y_offset);
49	
50	            x += glyph.x_advance.at(text.size);
51	            y += glyph.y_advance.at(text.size);
52	        }
53	    }
54	
55	    fn render_glyph(
56	        &mut self,
57	        svg: &mut SvgElem,
58	        state: &State,
59	        text: &TextItem,
60	        glyph_id: GlyphId,
61	        x_offset: Abs,
62	        y_offset: Abs,
63	    ) {
64	        if should_outline(&text.font, glyph_id) {
65	            // Pre-scale outlined glyphs, so strokes and fill patterns don't
66	            // need to consider text size glyph scaling.
67	            let scale = Ratio::new(text.size.to_pt() / text.font.units_per_em());
68	            let key = (&text.font, glyph_id, scale);
69	            let (id, path) = self.glyphs.insert_with_val(key, || {
70	                let mut builder = SvgPathBuilder::with_scale(scale);
71	                text.font.ttf().outline_glyph(glyph_id, &mut builder)?;
72	                Some(RenderedGlyph::Path(builder.finsish()))
73	            });
74	
75	            if path.is_some() {
76	                self.render_path_glyph(
77	                    svg, state, text, glyph_id, x_offset, y_offset, id,
78	                );
79	            }
80	        } else {
81	            // Image glyphs apply a `scale` at use site, since colr, svg-, and
82	            // bitmap glyph images are usually quite large, and having one glyph
83	            // per text size is a bit of a waste.
84	            let key = (&text.font, glyph_id);
85	            let (id, frame) = self.glyphs.insert_with_val(key, || {
86	                let frame = glyph_frame(&text.font, glyph_id.0)?;
87	                Some(RenderedGlyph::Frame(frame))
88	            });
89	
90	            if frame.is_some() {
91	                self.render_image_glyph(svg, x_offset, y_offset, text, id);
92	            }
93	        }
94	    }
95	
96	    /// Write a reference to an image glyph that is stored in font units.
97	    fn render_image_glyph(
98	        &mut self,
99	        svg: &mut SvgElem,
100	        x_offset: Abs,
101	        y_offset: Abs,
102	        text: &TextItem,
103	        id: DedupId,
104	    ) {
105	        let scale = Ratio::new(text.size.to_pt() / text.font.units_per_em());
106	        // Flip the transform again, since images are drawn Y-Down.
107	        let ts = Transform::translate(x_offset, y_offset)
108	            .pre_concat(Transform::scale(scale, -scale));
109	
110	        svg.elem("use")
111	            .attr("xlink:href", SvgIdRef(id))
112	            .attr("transform", SvgTransform(ts));
113	    }
114	
115	    /// Render a pre-scaled path glyph defined by an outline.
116	    #[expect(clippy::too_many_arguments)]
117	    fn render_path_glyph(
118	        &mut self,
